"""Returns the n_th pentagonal number. If fed with a negative number, it returns an
    extended pentagonal number.
    """
def pentagonal(n: int) -> int {
    return ((n * ((3 * n) - 1)) // 2);
}

"""
    Computes Euclidean distance squared
    """
def dist2(x1: Any, y1: Any, x2: Any, y2: Any) -> object {
    return (((x2 - x1) ** 2) + ((y2 - y1) ** 2));
}

"""
    Gets the url for a page containing information for specified game from NHL API.

    :param season: int, the season
    :param game: int, the game

    :return: str, https://statsapi.web.nhl.com/api/v1/game/[season]0[game]/feed/live
    """
def get_game_url(season: Any, game: Any) -> object {
    return 'https://statsapi.web.nhl.com/api/v1/game/{0:d}0{1:d}/feed/live'.format(
        season, game
    );
}

"""Generate binary coordinates."""
def get_binary_indexes(coordinates: Any) -> object {
    bin_coordinates = [];
    for coord in coordinates {
        coord = (
            "{:08b}".format(coord[0]),
            "{:08b}".format(coord[1]),
            "{:08b}".format(coord[2])
        );
        bin_coordinates.append(coord);
    }
    return bin_coordinates;
}

"""Tries to read an option from a dictionary. If not found, a
    standard value is returned instead. If no standard value is
    informed, None is returned. Data can also be converted by
    a type cast.
    The given standard value is not converted by typecast.

    WITH typecast=None, THIS CAN BE REPLACED BY dict.get() METHOD!
    """
def read_optional_from_dict(
    input_dict: Any, key: Any, standard_val: Any = None, typecast: Any = None
) -> object {
    try {
        val = input_dict[key];
    } except KeyError {
        return standard_val;
    }
    if (typecast is None) {
        return val;
    } else {
        return typecast(val);
    }
}

