"""Compute the squares of all the natural numbers in a range."""
def compute_all_squares(of_range: Any) -> object {
    squares = [];
    for i in range(of_range) {
        squares.append((i * i));
    }
    return squares;
}

"""Pick one item from each of categories."""
def pick_equipment(categories: Any, cur_pick: Any) -> object {
    if not categories {
        return [cur_pick];
    }
    items = categories[0];
    picks = [];
    for item in items {
        next_picks = pick_equipment(categories[1:], (cur_pick + item));
        picks.extend(next_picks);
    }
    return picks;
}

