def pick_equipment(categories, cur_pick):
    """Pick one item from each of categories."""
    if not categories:
        return [cur_pick]
    items = categories[0]
    picks = []
    for item in items:
        next_picks = pick_equipment(categories[1:], cur_pick + item)
        picks.extend(next_picks)
    return picks

